#!/usr/bin/env python3
"""
🔐 زنار — سكريبت استخراج الملفات
يستخرج جميع القوالب والملفات تلقائياً أثناء بناء Render
"""
import os, sys, json, base64, zlib

BLOB = ""

def extract():
    compressed = base64.b64decode(BLOB)
    raw = zlib.decompress(compressed)
    files = json.loads(raw.decode("utf-8"))
    
    base = os.path.dirname(os.path.abspath(__file__))
    extracted = 0
    for rel_path, content_b64 in files.items():
        full_path = os.path.join(base, rel_path)
        os.makedirs(os.path.dirname(full_path), exist_ok=True)
        content = base64.b64decode(content_b64)
        with open(full_path, "wb") as f:
            f.write(content)
        extracted += 1
        print(f"  ✅ {rel_path}")
    
    print(f"\n✅ تم استخراج {extracted} ملف بنجاح!")

if __name__ == "__main__":
    print("📦 زنار — استخراج الملفات...")
    extract()
